import asyncio
from dotenv import load_dotenv
load_dotenv()

from langgraph.checkpoint.memory import InMemorySaver
from cruscotto_agent.graph import build_graph

async def main():
    checkpointer = InMemorySaver()
    graph = await build_graph(checkpointer=checkpointer)
    config = {"configurable": {"thread_id": "local-test"}}
    
    # Response 1
    response1 = await graph.ainvoke(
        {"messages": [{"role": "user", "content": """Agisci come un team composto da data scientist, data analyst, economista territoriale, product strategist e consulente di municipal intelligence. Il tuo obiettivo è analizzare Montesilvano (PE) in modo sistematico e costruire, esclusivamente attraverso gli strumenti MCP `search_comune` e `comune_kpi` a tua disposizione, un sistema di conoscenza e benchmarking che permetta di individuare punti di forza, debolezze relative, opportunità, anomalie, trend, comuni comparabili e aree nelle quali Montesilvano può migliorare rispetto a territori simili. NON utilizzare fonti esterne, NON utilizzare dati provenienti dalla tua conoscenza generale, NON inventare KPI, valori, anni, definizioni o informazioni mancanti: ogni dato numerico deve provenire direttamente da una risposta MCP oppure essere ottenuto tramite un calcolo matematico esplicito effettuato su dati MCP. Inizia identificando tramite `search_comune` il comune di Montesilvano e utilizzando poi `comune_kpi` recupera il maggior numero possibile di informazioni disponibili sul comune; devi esplorare e comprendere integralmente la struttura dell'output di `comune_kpi`, identificando tutti i KPI, le categorie, le unità di misura, i periodi temporali, le eventuali serie storiche, i valori mancanti e ogni altra informazione disponibile. Dopo aver costruito il profilo completo di Montesilvano, devi interrogare sistematicamente `search_comune` e `comune_kpi` per un insieme sufficientemente ampio di comuni italiani, selezionati in modo da poter costruire gruppi di confronto statisticamente e territorialmente sensati; non limitarti ai comuni geograficamente vicini a Montesilvano e non assumere che la vicinanza geografica equivalga a comparabilità. Utilizza i KPI effettivamente disponibili per individuare comuni comparabili sulla base, quando possibile, di popolazione, caratteristiche demografiche, struttura socioeconomica, reddito, lavoro, finanza pubblica, investimenti, turismo, ambiente, infrastrutture, mobilità e qualsiasi altra dimensione realmente presente nei dati MCP. Costruisci quindi un peer group di Montesilvano e spiega, esclusivamente sulla base dei dati disponibili, perché ogni comune è stato considerato comparabile. Per Montesilvano e per ciascun peer raccogli una matrice omogenea di KPI e calcola, quando matematicamente possibile, valori assoluti, medie, mediane, minimi, massimi, percentili, differenze assolute, differenze percentuali, rapporti, variazioni temporali e distanza dal benchmark. Non creare un punteggio complessivo arbitrario e non definire Montesilvano "migliore" o "peggiore": descrivi invece oggettivamente dove il suo valore è superiore, inferiore o vicino al benchmark dei peer. Individua automaticamente i KPI nei quali Montesilvano presenta valori particolarmente elevati rispetto ai comuni comparabili e quelli nei quali presenta valori particolarmente bassi; per ogni differenza identifica anche quali comuni peer presentano valori più elevati o più bassi e quantifica lo scostamento. Quando sono disponibili serie temporali, analizza l'evoluzione di Montesilvano e verifica se il gap rispetto ai peer aumenta, diminuisce o rimane sostanzialmente stabile. Individua quindi le aree che possono essere considerate opportunità di miglioramento sulla base della distanza osservata dal benchmark, senza trasformare automaticamente ogni valore basso in una criticità e senza attribuire cause che non siano dimostrabili dai dati MCP. Per ogni opportunità individua i comuni comparabili che presentano valori più favorevoli e trattali come casi di benchmark da studiare, senza affermare che il loro risultato sia causalmente trasferibile a Montesilvano. Calcola inoltre scenari puramente quantitativi nei quali Montesilvano raggiunga, quando abbia senso matematico farlo, la mediana o altri benchmark del proprio peer group, mostrando esclusivamente la variazione numerica che ne deriverebbe e senza stimare effetti economici, sociali o politici che non siano direttamente calcolabili dai dati disponibili. Costruisci una vera e propria 'Montesilvano Intelligence Map' composta da: profilo attuale, punti di forza relativi, gap relativi, trend, peer comparabili, benchmark da studiare, KPI anomali, KPI in miglioramento, KPI in peggioramento e KPI da monitorare. Successivamente ragiona come un product strategist e determina quali prodotti o servizi commerciali possono essere costruiti esclusivamente a partire da queste informazioni: profilo comunale, benchmark tra comuni, peer finder, municipal due diligence, location intelligence, monitoraggio finanziario, monitoraggio territoriale, report automatici e AI analyst. Per ciascun possibile prodotto indica quali dati MCP lo alimentano, quale problema risolve, quale tipo di cliente potrebbe utilizzarlo, quali operazioni matematiche richiede e quali limiti presenta. Identifica infine il prodotto con il maggiore potenziale di valore commerciale sulla base della quantità, profondità, comparabilità e aggiornabilità dei dati effettivamente disponibili, senza inventare dati che non esistono. Il risultato finale deve essere un'analisi completa ma operativa che possa essere trasformata direttamente in un prodotto software dedicato a Montesilvano: deve includere il profilo dati del comune, la matrice dei KPI, il peer group, i benchmark, i gap, le opportunità, i trend, gli indicatori derivati calcolabili, gli algoritmi di confronto possibili, le query MCP necessarie per ottenere i dati, la struttura logica del database risultante, le funzionalità che il software dovrebbe offrire, gli output che dovrebbe produrre e il modello di business potenziale. Devi essere estremamente rigoroso nel distinguere quattro livelli: (1) dato direttamente restituito dall'MCP, (2) calcolo matematico derivato dai dati MCP, (3) interpretazione analitica, (4) ipotesi o proposta di prodotto. Non confondere mai questi livelli. Quando un'informazione non è disponibile attraverso `search_comune` o `comune_kpi`, dichiaralo esplicitamente invece di cercare di ricostruirla con conoscenza esterna. L'obiettivo non è produrre un semplice report su Montesilvano, ma scoprire quale sistema di municipal intelligence sia possibile costruire utilizzando esclusivamente questi due strumenti MCP e trasformare la conoscenza ottenuta in un prodotto concreto, ripetibile, automatizzabile e potenzialmente vendibile."""}]},
        config,
    )
    for msg in response1["messages"]:
        if msg.type == "ai" and getattr(msg, "tool_calls", None):
            print([tc["name"] + " " + str(tc["args"]) for tc in msg.tool_calls])
    print(response1["messages"][-1].content)

if __name__ == "__main__":
    asyncio.run(main())